package com.nimbusbill.customer.entity;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.*; import java.util.UUID;
@Entity @Table(name="customer_tax_profiles") public class CustomerTaxProfile {
 @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @OneToOne(optional=false) @JoinColumn(name="customer_id",unique=true) private Customer customer; @Column(name="tax_identifier",length=40) private String taxIdentifier; @Column(name="tax_country",nullable=false,length=2) private String taxCountry; @Column(name="tax_region",length=80) private String taxRegion; @Column(name="place_of_supply",length=80) private String placeOfSupply; @Column(name="default_tax_rate",nullable=false,precision=8,scale=4) private BigDecimal defaultTaxRate; @Column(name="tax_exempt",nullable=false) private boolean taxExempt; @Column(name="effective_from",nullable=false) private LocalDate effectiveFrom; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt; @PrePersist void create(){createdAt=Instant.now();updatedAt=createdAt;} @PreUpdate void update(){updatedAt=Instant.now();}
 public UUID getId(){return id;} public Customer getCustomer(){return customer;} public void setCustomer(Customer v){customer=v;} public String getTaxIdentifier(){return taxIdentifier;} public void setTaxIdentifier(String v){taxIdentifier=v;} public String getTaxCountry(){return taxCountry;} public void setTaxCountry(String v){taxCountry=v;} public String getTaxRegion(){return taxRegion;} public void setTaxRegion(String v){taxRegion=v;} public String getPlaceOfSupply(){return placeOfSupply;} public void setPlaceOfSupply(String v){placeOfSupply=v;} public BigDecimal getDefaultTaxRate(){return defaultTaxRate;} public void setDefaultTaxRate(BigDecimal v){defaultTaxRate=v;} public boolean isTaxExempt(){return taxExempt;} public void setTaxExempt(boolean v){taxExempt=v;} public LocalDate getEffectiveFrom(){return effectiveFrom;} public void setEffectiveFrom(LocalDate v){effectiveFrom=v;}
}
